thread_local! {
        pub(super) static PREFETCH_READS: Cell<usize> = const { Cell::new(0) };
    }

thread_local! {
        pub(super) static PREFETCH_READS: Cell<usize> = const { Cell::new(0) };
    }

std::thread_local! {
    /// Cancellation state of the innermost [`CancelOnDrop::scope`] on this thread.
    static CURRENT: RefCell<Option<Arc<AtomicU8>>> = const { RefCell::new(None) };
}

std::thread_local! {
    /// Cancellation state of the innermost [`CancelOnDrop::scope`] on this thread.
    static CURRENT: RefCell<Option<Arc<AtomicU8>>> = const { RefCell::new(None) };
}

thread_local! {
    static CLOCK: RefCell<Option<Rc<RefCell<Clock>>>> = const { RefCell::new(None) };
}

thread_local! {
    static CLOCK: RefCell<Option<Rc<RefCell<Clock>>>> = const { RefCell::new(None) };
}

std::thread_local! {
    // Shuttle tasks share one runner thread, but jobs retain their logical pool worker's state.
    static WORKERS: RefCell<std::collections::BTreeMap<(usize, usize), std::rc::Rc<WorkerSlot>>> =
        const { RefCell::new(std::collections::BTreeMap::new()) };
}

